contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params:
    // target: address to forward funds to (may be address(c) or any other)
    // value: amount of Wei to send along with sendMoney
    // data: calldata bytes passed to the low-level call inside sendMoney
    function run(address target, uint value, bytes memory data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // ensure this contract has enough Ether to fund any potential internal forwarding
        require(address(this).balance >= value, "insufficient balance for value");

        // Record C's balance before the attempted sendMoney call
        uint balBefore = address(c).balance;

        // Attempt to call sendMoney as the caller of run.
        bool reverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe C's balance after the call
        uint balAfter = address(c).balance;

        // General rule: If the call reverted, C's balance must be unchanged; if it did not revert,
        // then C's balance must have decreased by exactly value (since sendMoney forwards value to target on success).
        // Note: If sendMoney succeeds, it requires the low-level call to succeed and the transfer of `value` out of C.
        assert(reverted ? (balAfter == balBefore) : (balBefore >= value && balAfter == balBefore - value));
    }

    // Accept Ether if C forwards funds back to this test
    receive() external payable {}
}

